Tool response:
Tool: check_part_fitment
Description: Validate whether a given OEM part number is compatible with a 2022 Toyota Camry LE equipped with a 2.5L 4-cylinder engine. Uses built-in fitment matrix to determine compatibility.
Parameters:
    {
      "type": "object",
      "properties": {
        "oem_number": {
          "type": "string",
          "description": "The OEM part number to search for",
          "title": "Oem Number"
        },
        "year": {
          "type": "integer",
          "description": "Vehicle manufacturing year",
          "title": "Year"
        },
        "make_name": {
          "type": "string",
          "description": "Vehicle manufacturer name",
          "title": "Make Name"
        },
        "model_name": {
          "type": "string",
          "description": "Vehicle model name",
          "title": "Model Name"
        },
        "trim_name": {
          "type": "string",
          "description": "Vehicle trim level name",
          "title": "Trim Name"
        },
        "engine_displacement": {
          "type": "number",
          "description": "Engine displacement in liters",
          "title": "Engine Displacement"
        },
        "engine_cylinders": {
          "type": "integer",
          "description": "Number of engine cylinders",
          "title": "Engine Cylinders"
        }
      },
      "required": [
        "oem_number",
        "year",
        "make_name",
        "model_name",
        "trim_name",
        "engine_displacement",
        "engine_cylinders"
      ]
    }
